--- 判断是否天梯pvp解锁
---@return boolean
function ActionUtils.IsLadderPvpUnlocked()
    ---@type RegionEntryVo[]
    local t = CfUtils.GetCf(AutoIds.IdSetting3042, "RegionEntryVo", true)
    local isUnlocked = false
    for i, v in pairs(t) do
        if checkNumber(v.uid) == Constants.SystemToggleIds.Id2008 then
            isUnlocked  = GameUtils.IsUnlockedSingle(v.unlockType, v.unlockNum, v.unlockId)
            break
        end
    end
    return isUnlocked
end

--- 是否区域点存在天梯pvp
---@param regionId number
---@return boolean
function ActionUtils.IsRegionPointHaveLadderPvp(regionId)
    local t = ActionUtils.GetAllRegionSecondMapPointId(regionId)
    local havLadderPvp = false
    for _, id in pairs(t) do
        local vo = ActionUtils.GetRegionSecondaryMapVo(checkNumber(id))
        if checkNumber(vo.type) == Constants.RegionSecondMapPointType.LadderPvp then
            havLadderPvp = true
        end
    end
    return havLadderPvp
end

