--主线任务长连接通知
function ActionUtils.ShowMaintQestTaskNode(data)
    if checkNumber(KCookie.Get("UICommonMainlineTaskTipsNode")) == 1 then
        return 
    end
    Events.Broadcast(Constants.EventNames.MainQuestTaskChange, nil)

    ---@type GuideUtils
    local GuideUtils = import('Game.UI.Guide.GuideUtils')
    if GuideUtils.CheckIsOpenSpecifyGuide(Constants.GuideModule.CatBallDraw) then
        return
    end

    if checkNumber(data.type) == Constants.TaskType.MainTask then
        local questComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
        local taskData = questComponent:GetCurTaskInfo()
        local vo = QuestConfMgr:GetInstance():GetQuestVoById(data.questId)
        local taskVo = QuestConfMgr:GetInstance():GetMainTaskQuestVo(vo.task)
        --没完成
        if checkNumber(taskData.progress) < checkNumber(taskVo.taskContenNum) then
            return
        end
    else
        local vo = ActionUtils.GetRegionTaskVo(data.taskId)
        if not vo then 
            return
        end
        if checkNumber(data.progress) < checkNumber(vo.taskContenNum) then
            return
        end
    end

    --- 检查是否需要缓存数据到上一级弹出
    if UIModule.CurrentScreen and UIModule.CurrentScreen.Argument.id ~= Constants.UITypeIds.UISceneHome then
        return
    end
    ---@type Engine.UI.UIDialog
    local dialog = UIModule.CurrentScreen:LastDialog()
    if isNull(dialog) then
        return
    end
    local dialogId = checkNumber(dialog.Argument.id)
    if dialogId == Constants.UITypeIds.UIMaidCoffeeTakeoutPopupDialog 
    or dialogId == Constants.UITypeIds.CatBallCultivateDialog 
    then
        KCookie.Set(Constants.UICacheDataKeys.TASK_TIPS_DATA, {dialogId = dialogId, data = data})
        return
    else
        KCookie.Set(Constants.UICacheDataKeys.TASK_TIPS_DATA)
    end

    if dialogId == Constants.UITypeIds.UICommonRewardPop or 
    --  dialogId == Constants.UITypeIds.UIMaidCoffeeTakeoutPopupDialog or
     dialogId == Constants.UITypeIds.OverseaManageCatballControlDialog or
     dialogId == Constants.UITypeIds.UICultivateLevelUpFinishDialog or
     dialogId == Constants.UITypeIds.OverseaManageCatballStarupPopup or
     dialogId == Constants.UITypeIds.CultivateLevelUpSecondConfirmPanel or
     dialogId == Constants.UITypeIds.OverseaManageCatballLevelupPopup or
     dialogId == Constants.UITypeIds.UICommonChestUsePopUpDialog or
     dialogId == Constants.UITypeIds.OverseaManageVipOrderTips or
     dialogId == Constants.UITypeIds.UIFastNettingFishDialog or 
     dialogId == Constants.UITypeIds.IdolLive3D_MainUI
    then
        ---通用弹出窗口排除
        local dialogs = UIModule.CurrentScreen.dialogs
        local len = dialogs.Count
        if len >= 2 then
            dialog = dialogs[ len - 2]---取前一级窗口
        end
    end
    ActionUtils.ShowTaskTipsNode(dialog, data)

end

function ActionUtils.ShowTaskTipsNodeByDialog(dialog, dialogId)
    local cookieData = KCookie.Get(Constants.UICacheDataKeys.TASK_TIPS_DATA)
    if cookieData == nil then return end
    if cookieData.dialogId ~= dialogId then return end
    KCookie.Set(Constants.UICacheDataKeys.TASK_TIPS_DATA)
    if checkNumber(KCookie.Get("UICommonMainlineTaskTipsNode")) == 1 then
        return 
    end
    ActionUtils.ShowTaskTipsNode(dialog, cookieData.data)

end

function ActionUtils.ShowTaskTipsNode(dialog, data)
    if isNull(dialog) then
        return
    end
    print("====>>", dialog.Argument.id)
    ---@type Engine.Modules.AbstractResourceLoader
    local loader = ResourceModule.LoadBundleSync("Prefabs/Common/CommonMainlineTaskTipsNode.prefab", nil, true)
    if loader.IsSuccess then
        local go = loader:Instantiate(dialog.transform, false)
        go.name = "CommonMainlineTaskTipsNode"
        if not KTool.IsNull(go) then
            local t = go:GetComponent(typeof(RectTransform))
            t.anchorMin = Vector2.zero
            t.anchorMax = Vector2.one
            t.offsetMin = Vector2.zero
            t.offsetMax = Vector2.zero
            t.localPosition = Vector3.zero
            t.localRotation = Quaternion.identity
            t.localScale = Vector3.one
            go.layer = dialog.gameObject.layer

            KCookie.Set("UICommonMainlineTaskTipsNode", 1)
            ---获取lua脚本然后执行方法
            ---@type UICommonMainlineTaskTipsNode
            local scr = CfUtils.GetLuaScr(go, "Game.UI.FightReady.UIMainChapter.UICommonMainlineTaskTipsNode")
            if scr then
                scr:Refresh(data)
                Events.Broadcast(Constants.EventNames.UICommonMainlineTaskTipsNodeEventName, {luaEnv = scr})
            end
        end
        loader:Release(true)
    end
end

