--是否解锁区域关卡
function ActionUtils.IsUnlockRegionQuest(id)
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(id)
    if not vo then
        return false, ""
    end

    local mapVo = ActionUtils.GetRegionSecondaryMapVo(vo.pointID) 
    local t = ActionUtils.GetRegionalData(mapVo.regionBelong)

    local data = checkTable(t.regionQuestInfo)
    local questInfo = checkTable(data[checkString(vo.pointID)])

    local isUnlockQuest = ActionUtils.IsPassRegionQuest(vo.unlockLevel) --(checkNumber(questInfo.questId) >= checkNumber(vo.unlockLevel))
    local isUnlockLikabilityLv = true
    local str2 = ""
    if checkNumber(vo.unlockType) > 0 and checkNumber(vo.unlockNum) > 0 then
        isUnlockLikabilityLv = GameUtils.IsUnlockedSingle(checkString(vo.unlockType), checkString(vo.unlockNum), checkString(vo.unlockId))
        str2 = GameUtils.GetUnlockDescr(checkString(vo.unlockType), checkString(vo.unlockNum), checkString(vo.unlockId))
    else
        str2 = localize("通关前置关卡解锁")
    end
    local str1 = ""---

    if not isUnlockQuest then
        return false, str1..str2
    end

    if not isUnlockLikabilityLv then 
        return false,  str1..str2
    end

    return isUnlockQuest and isUnlockLikabilityLv
end

--是否解锁歼灭战关卡
function ActionUtils.IsUnlockAnnihilationQuest(id, mapId)
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(id)
    if not vo then
        return false, ""
    end
    local t = ActionUtils.GetRegionalData(mapId)
    local data = checkTable(t.regionalBossData)

    return checkNumber(data.openQuestId) >= checkNumber(vo.id)
end

