                        scr:Refresh(jsonData)
                    end
                end
            end
        end, true, UIModule.RootCanvas.transform)
    else
        if not KTool.IsNull(go) then
            local scr = CfUtils.GetLuaScr(go, "Game.UI.FightReady.UIMainChapter.ActionTeamInviteNode")
