end

function ActionUtils.GetFishPointVo(mapId)
    if checkNumber(mapId) <= 0 then
        return nil
    end
    local t = ActionUtils.GetAllRegionSecondMapPointId(mapId)
    if t then
        for k, id in pairs(t) do
            local vo = ActionUtils.GetRegionSecondaryMapVo(id)
            if vo then
                if checkNumber(vo.type) == Constants.RegionSecondMapPointType.Fish then
                    return vo
                end
            end
        end
    end
    return nil
end

