    end
    local time = checkNumber(vo.num)
    local playerComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerDojo = playerComponent.playerDojo
    if playerDojo then
        ---@type WelfareSettingVo
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting4032, "WelfareSettingVo", 1)
        local isHavePrivilegeCard = playerDojo:IsHavePrivilegeCardById(tonumber(vo.giftId))
        if isHavePrivilegeCard then
            local addNum = GameUtils.GetPrivilegeCardAddNumByName(checkNumber(vo.giftId), "keyTime")
            time = time * addNum
        end
    end

    return time
end

