function ActionUtils.UpdateLikabilityLvExp(data)
    if not data then
        return
    end
    local goodsId = checkNumber(data.goodsId)
    local num = checkNumber(data.num)

    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    if not vo then
        return
    end

    if checkNumber(vo.effectType) ~= Constants.GoodsEffectType.RegionLikability then
        return
    end

    --最大了
    local isMax = ActionUtils.IsMaxLikabilityLevel(vo.effectId)
    if isMax then
        return
    end

    local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.ActionComponent)
    local curLv, exp = comp:GetLikabilityLvExp(vo.effectId)
    -----TODO why this judgement
    --if checkNumber(curLv) <= 0 then
    --    return
    --end
    exp = checkNumber(exp) + checkNumber(vo.effectNum) * num
    local upLevel = ActionUtils.GetLevelUpNum(vo.effectId)
    if exp >= upLevel then
        curLv = curLv + 1
        exp = exp - upLevel
        comp:SetLevelUpCookie(vo.effectId, curLv)
        ---触发了好感度升级, 刷新一次外卖数据
        Events.Broadcast(Constants.EventNames.EVENT_TAKEOUT_POPUP_FINISHED, {isNewOrder = 1})
    end
    comp:UpdateLikabilityLvExp(vo.effectId, curLv, exp)

    Events.Broadcast(Constants.EventNames.RegionLikability, nil)
end

