function ActionUtils.HandleMainQuestPass(id)
    local isPass = QuestConfMgr:GetInstance():IsPassQuest(id)
    if isPass then
        return
    end

    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActionComponent)
    ---@type RegionSecondaryMapVo[]
    local t = CfUtils.GetCf(AutoIds.IdSetting3021, "RegionSecondaryMapVo", true)
    for k, v in pairs(t) do
        if checkNumber(v.unlockType) == Constants.CommonUnlockType.PassQuest and checkNumber(v.unlockNum) == checkNumber(id) then
            comp:AddUnlockPointIds(v.id)
            ActionUtils.AddRedPointIds(v.id)
        end
    end
end

