function ActionUtils.GetCurRegionQuestId(regionId, type)
    if type == 0 then
        return 0
    end
    local vo = ActionUtils.GetRegionSecondaryMapVo(regionId)

    local newQuestId = 0
    if checkNumber(vo.type) == Constants.RegionSecondMapPointType.Sp then
        local vo = ActionUtils.GetRegionDailyTypeVo(type)
        local t = checkTable(CfUtils.Split(vo.content))

        local dailyQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.DailyQuestComponent)
        local data = checkTable(dailyQuestComponent:GetDailyQuestData(type))
        newQuestId = checkNumber(data.newestPassedQuest)

        for k, v in pairs(t) do
            if QuestConfMgr:GetInstance():IsUnlockQuest(v) then
                if checkNumber(v) > newQuestId then
                    return v
                end
            end
        end
    else
        local t = ActionUtils.GetRegionalData(vo.regionBelong)
        local data = checkTable(t.regionQuestInfo)
        local questInfo = checkTable(data[checkString(vo.id)])
        newQuestId = checkNumber(questInfo.questId)

        local t = checkTable(CfUtils.Split(vo.content))
        for k, v in pairs(t) do
            vo = QuestConfMgr:GetInstance():GetQuestVoById(v)
            if checkNumber(vo.levelType) == checkNumber(type) then
                if ActionUtils.IsUnlockRegionQuest(v) then
                    if checkNumber(v) > newQuestId then
                        return v
                    end
                end
            end
        end
    end

    return newQuestId
end

