function ActionUtils.IsHasTasksOrMapRedPoint()
    local mapVos = ActionUtils.GetAllRegionPrimaryMapVo()
    local isHave = false
    for i, v in pairs(mapVos) do
        local isHave = ActionUtils.IsAreaHaveRedPoint(v.id)
        if isHave then
            return true
        end
    end
    return isHave
end

function ActionUtils.IsAreaHaveRedPoint(id)
    local isHaveTask = ActionUtils.IsHasTaskCanDraw(id)
    local isHaveMap = ActionUtils.IsShowMapRedpoint(id)
    return isHaveTask or isHaveMap
end

function ActionUtils.IsHasTaskCanDraw(id)
    local lv, exp = ActionUtils.GetRegionalPointLikabilityLevel(id)
    local isMax = ActionUtils.IsMaxLikabilityLevel(id)
    if isMax then
        return false
    end
    local num1, num2 = ActionUtils.GetTaskNumBuyHomeData(id, lv)
    if num1 >= num2 then
        local vo = ActionUtils.GetRegionLikabilityVo(ActionUtils.GetRegionLikabilityId(id, lv))
        if GoodsUtils.GetThingNo(vo.levelUpCost) >= checkNumber(vo.levelUpNum) then
            return true
        end
    end

    local t = ActionUtils.GetAllRegionSecondMapPointId(id)
    local taskPointVo
    for k, id in pairs(t) do
        local vo = ActionUtils.GetRegionSecondaryMapVo(checkNumber(id))
        if checkNumber(vo.type) == Constants.RegionSecondMapPointType.Task then
            taskPointVo = vo
        end
    end
    if not isNull(taskPointVo) then
        local vo = taskPointVo
        local isUnlock = GameUtils.IsUnlockedSingle(checkString(vo.unlockType), checkString(vo.unlockNum), checkString(vo.unlockId))
        if isUnlock then
            local data = ActionUtils.GetRegionalData(id)
            return checkNumber(data.canReceiveTask) > 0
        end
    end

    return false
end

function ActionUtils.IsShowMapRedpoint(id)
    local t = ActionUtils.GetAllRegionSecondMapPointId(id)
    for k, v in pairs(t) do
        if ActionUtils.IsShowRedpoint(v) then
            return true
        end
    end
    return false
end

function ActionUtils.IsShowRedpoint(id)
    if checkNumber(id) <= 0 then
        return false
    end
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActionComponent)
    local t = comp:GetRedPointIds()

    for k, v in pairs(t) do
        if checkNumber(id) == checkNumber(v) then
            return true
        end
    end
    return false
end

