function ActionUtils.GetTaskFinishNum()
    local ActionComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActionComponent)
    local t = ActionComponent:GetAllTask()

    local finishTask = 0
    local taskNum = 0
    for k, v in pairs(t) do
        for _, data in pairs(v) do
            if checkNumber(data.status) == 2 then
                finishTask = finishTask + 1
            end
            taskNum =  taskNum + 1
        end
    end

    return finishTask, taskNum
end

