--是否解锁任务
function ActionUtils.IsUnlockTask(id)
    local vo = ActionUtils.GetRegionTaskVo(id)
    if not vo then
        return false
    end

    if checkNumber(vo.before) <= 0 then
        return true
    end
    local isMax = ActionUtils.IsMaxLikabilityLevel(vo.regionBelong)
    if isMax then
        return true
    end

    return ActionUtils.IsDrawTask(vo.before)
end

function ActionUtils.IsDrawTask(id)
    local ActionComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActionComponent)
    local t = ActionComponent:GetAllTask()

    local vo = ActionUtils.GetRegionTaskVo(id)
    if not vo then
        return false
    end
    local isMax = ActionUtils.IsMaxLikabilityLevel(vo.regionBelong)
    if isMax then
        return true
    end

    t = t[checkString(vo.taskGroup)]
    if not t then
        return false
    end

    t = t[checkString(vo.id)]
    if not t then
        return false
    end
    return checkNumber(t.status) == 2
end

function ActionUtils.IsCanDrawTask(id)
    local ActionComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActionComponent)
    local t = ActionComponent:GetAllTask()

    local vo = ActionUtils.GetRegionTaskVo(id)
    if not vo then
        return false
    end
    local isMax = ActionUtils.IsMaxLikabilityLevel(vo.regionBelong)
    if isMax then
        return false
    end

    t = t[checkString(vo.taskGroup)]
    if not t then
        return false
    end

    t = t[checkString(vo.id)]
    if not t then
        return false
    end
    return checkNumber(t.status) == 1
end


