--- 当前是否可以跳转到歼灭战的检查
function ActionUtils.CanJump()
    local ShowToast = function()
        GameUtils.Toast(localize('【当前场景不可前往协力战，请先回到主界面】'))
    end
    local dialog = UIModule.CurrentScreen:LastDialog()
    if checkNumber(dialog.Argument.id) == Constants.UITypeIds.UICommonRewardPop or
            checkNumber(dialog.Argument.id) == Constants.UITypeIds.UIMaidCoffeeTakeoutPopupDialog or
            checkNumber(dialog.Argument.id) == Constants.UITypeIds.OverseaManageCatballControlDialog or
            checkNumber(dialog.Argument.id) == Constants.UITypeIds.UICultivateLevelUpFinishDialog or
            checkNumber(dialog.Argument.id) == Constants.UITypeIds.OverseaManageCatballStarupPopup or
            checkNumber(dialog.Argument.id) == Constants.UITypeIds.CultivateLevelUpSecondConfirmPanel or
            checkNumber(dialog.Argument.id) == Constants.UITypeIds.OverseaManageCatballLevelupPopup or
            checkNumber(dialog.Argument.id) == Constants.UITypeIds.LadderStruggleResultDialog or
            checkNumber(dialog.Argument.id) == Constants.UITypeIds.LadderCompetionMatchDialog or
            checkNumber(dialog.Argument.id) == Constants.UITypeIds.OverseaManageVipOrderTips then
        ShowToast()
        return false
    end
    local skipButtonTrans = UIModule.RootCanvas.transform:Find("ShowCommonSkipButton")
    if not isNull(skipButtonTrans) then
        ShowToast()
        return false
    end
    local FishingMgr = import('Game.UI.Fishing.FishingMgr')
    local sceneId = FishingMgr:GetInstance():GetCurFishSceneId()
    local sceneManagement = SceneManagement:GetInstance()
    local fishingScene = sceneManagement:GetSceneInstance(tostring(sceneId))
    if not isNull(fishingScene) then
        --在钓鱼的过程中屏蔽
        ShowToast()
        return false
    end
    local movieTrans = UIModule.RootCanvas.transform:Find("GachaponEntryBg")
    if not isNull(movieTrans) then
        ShowToast()
        return false
    end
    ---@type GachaponConstants
    local GachaponConstants = import('Game.Gachapon.GachaponConstants')
    local sceneSettingId  = GachaponConstants.GachaponGuideAnimSceneDefine.SCENE_ID
    local sceneInstance = SceneManagement:GetInstance():GetSceneInstance(sceneSettingId)
    local drawCardGo = sceneInstance:GetCacheObjectByName("GachaponCache")
    if not isNull(drawCardGo) then
        local drawTrans = drawCardGo.transform
        local isOk = true
        for i = 1, drawTrans.childCount do
            local trans = drawTrans:GetChild(i - 1)
            if KTool.IsActive(trans.gameObject) then
                isOk = false
                break
            end
        end
        if not isOk then
            ShowToast()
            return false
        end
    end
    
    return true
end

return ActionUtils
